public static class DesktopActionIcons {
    public static string DirectoryPath;
    static readonly Dictionary<string,Image> images=new Dictionary<string,Image>();
    public static Image Get(string name,string tone){
        if(String.IsNullOrEmpty(DirectoryPath)||String.IsNullOrEmpty(name))return null;
        string key=name+"-"+tone;
        if(!images.ContainsKey(key)){string file=Path.Combine(DirectoryPath,key+".png");if(!File.Exists(file))return null;using(var source=Image.FromFile(file))images[key]=new Bitmap(source);}
        return images[key];
    }
}
