        using(var path=new GraphicsPath()){path.AddArc(r.X,r.Y,radius,radius,180,90);path.AddArc(r.Right-radius,r.Y,radius,radius,270,90);path.AddArc(r.Right-radius,r.Bottom-radius,radius,radius,0,90);path.AddArc(r.X,r.Bottom-radius,radius,radius,90,90);path.CloseFigure();Color fill=Enabled?BackColor:Color.FromArgb(32,36,40);if(hover&&Enabled)fill=ControlPaint.Light(fill,.12f);using(var brush=new SolidBrush(fill))e.Graphics.FillPath(brush,path);using(var pen=new Pen(Color.FromArgb(52,57,63)))e.Graphics.DrawPath(pen,path);}
