    Image NavigationIcon(Dictionary<string,object> map,bool region){try{using(var stream=File.OpenRead(Path.Combine(root,"lordnine","maps",Str(map,"image"))))using(var bitmap=new Bitmap(stream)){double[] ys={.250,.337,.423,.507,.590};int tab=Convert.ToInt32(map["tab_index"]);double y=region?(tab>=1&&tab<=ys.Length?ys[tab-1]:ys[0]):Convert.ToDouble(Arr(map["select_point"])[1]);var rect=Rectangle.FromLTRB((int)(bitmap.Width*(region?.006:.045)),(int)(bitmap.Height*(y-(region?.040:.042))),(int)(bitmap.Width*(region?.040:.085)),(int)(bitmap.Height*(y+(region?.040:.042))));using(var crop=bitmap.Clone(rect,bitmap.PixelFormat))return new Bitmap(crop,28,28);}}catch{return null;}}
    void SelectCatalogMap(int index){if(index<0||index>=mapItems.Count)return;int spot=points.FindIndex(p=>Str(p,"map_id")==Str(mapItems[index],"id"));spots.SelectedIndex=spot;maps.SelectedIndex=index;RefreshNavigation();RefreshPointList();}
