        foreach(string name in regions.Items){string value=name;int count=mapItems.FindAll(m=>Str(m,"tab_label")==value).Count;var button=new BotButton{Text=value,NavigationCount=count,Image=NavigationIcon(mapItems.Find(m=>Str(m,"tab_label")==value),true),OwnsImage=true,AccessibleName="Регион "+value,Height=52,BackColor=value==region?Color.FromArgb(38,62,52):Surface,ForeColor=value==region?Mint:Color.White,Margin=new Padding(0,0,4,6),Font=new Font("Segoe UI",9)};toolTips.SetToolTip(button,value);button.Click+=(s,e)=>SelectCatalogMap(mapItems.FindIndex(m=>Str(m,"tab_label")==value));regionNavigation.Controls.Add(button);}
