    void UpdateGameView(){
        gameSelect.Enabled=!busy&&gameModules.Count>0&&(String.IsNullOrEmpty(deviceId)||deviceAvailable);
        var module=gameModules.Find(m=>Str(m,"id")==chosenGame);moduleVersion=module==null?"":Str(module,"version");moduleLabel.Text=module==null?"Модуль недоступен":deviceTabs==null?Str(module,"name")+" · модуль "+moduleVersion:"Модуль "+moduleVersion;
        if(automationHeading!=null){
            automationHeading.Text=(module==null?"Игра":Str(module,"name"))+" · Автоматизация";
            if(automationGame!=chosenGame){
                if(automationHeading.Image!=null){automationHeading.Image.Dispose();automationHeading.Image=null;}
                string file=System.Text.RegularExpressions.Regex.IsMatch(chosenGame??"","^[a-z][a-z0-9_-]{0,40}$")?Path.GetFullPath(Path.Combine(root,"..","pc","assets","bots",chosenGame+".png")):"";
                if(File.Exists(file)){using(var image=Image.FromFile(file))automationHeading.Image=new Bitmap(image,32,32);}
                else{var fallback=DesktopActionIcons.Get("bot","light");if(fallback!=null)automationHeading.Image=new Bitmap(fallback,32,32);}
                automationGame=chosenGame;
            }
        }
        gameSettingsNotice.Text=chosenGame!=profileGame?"Игра ещё не назначена этому телефону.":LordNineSettings?"":"Настройки этой игры пока недоступны в клиенте.";
        foreach(var check in new[]{farm,recovery,dismantle,autostart}){check.Visible=LordNineSettings;check.Enabled=LordNineSettings&&!busy;}
        if(gameAutomation!=null)gameAutomation.Visible=LordNineSettings;
        if(deviceTabs!=null)deviceTabs.SetPageAvailable(1,LordNineSettings);
        foreach(var action in actions){bool available=(String.IsNullOrEmpty(deviceId)||deviceAvailable)&&settings!=null&&!busy;string name=action.Text;if(name=="Назначить")available&=module!=null&&chosenGame=="lordnine";else if(name=="Скачать / установить"||name=="Обновить")available&=module!=null&&chosenGame==profileGame;else if(name.Contains("настройки")||name.Contains("профиль MultiBot")||name.Contains("фарм"))available&=LordNineSettings;action.Enabled=available;}
    }
    async Task AssignGame(){if(String.IsNullOrEmpty(chosenGame))return;if(chosenGame!="lordnine"){status.Text="Назначение этой игры пока не поддерживается клиентом.";return;}if(dirty){status.Text="Сначала сохраните или отмените изменения текущей игры.";return;}if(chosenGame!=profileGame&&MessageBox.Show(this,"Назначить игру «"+Convert.ToString(gameSelect.SelectedItem)+"» этому телефону? Настройки другой игры не переносятся.","Смена игры",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;await Action("assign",chosenGame);profile=null;await LoadProfile();}
    static IEnumerable<Control> SnapshotControls(Control parent){foreach(Control control in parent.Controls)yield return control;}
    static string ActionIcon(string text){switch(text){case "Запустить":return "play";case "Пауза":return "pause";case "Продолжить":return "step-forward";case "Остановить":return "square";case "Скачать / установить":return "download";case "Обновить":return "refresh-cw";case "Откат":return "undo-2";case "Статус":return "info";case "Назначить":return "check";default:return null;}}
    void AddAction(Control container,string text,Func<Task> action){var b=new BotButton{Text=text,ActionIconName=ActionIcon(text),AccessibleName=text,Width=142,Height=46,BackColor=Surface,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};if(container is FlowLayoutPanel && ((FlowLayoutPanel)container).FlowDirection==FlowDirection.TopDown){b.Width=294;b.Height=44;}actions.Add(b);container.Controls.Add(b);toolTips.SetToolTip(b,text);buttonCommands[b]=async()=>await Guard(action);b.Click+=(s,e)=>buttonCommands[b]();}
    void PointButton(Control container,string text,Action action){var b=new BotButton{Text=text,AutoSize=true,MinimumSize=new Size(0,38),Padding=new Padding(8,3,8,3),BackColor=Surface,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};if(container is FlowLayoutPanel && ((FlowLayoutPanel)container).FlowDirection==FlowDirection.TopDown){b.AutoSize=false;b.Width=294;b.Height=40;}container.Controls.Add(b);buttonCommands[b]=()=>{if(settings!=null&&!busy)action();};b.Click+=(s,e)=>buttonCommands[b]();}
    async Task Guard(Func<Task> action){if(selected==null||(!String.IsNullOrEmpty(deviceId)&&(!deviceAvailable||settings==null))){status.Text="Настройки выбранного телефона недоступны.";return;}busy=true;UpdateGameView();try{await action();}catch(Exception error){status.Text="Операция не выполнена: "+error.Message;}finally{busy=false;UpdateGameView();}}
    async Task<Dictionary<string,object>> Request(string method,string url,object body=null){using(HttpResponseMessage response=method=="GET"?await http.GetAsync(url):await http.PostAsync(url,new StringContent(json.Serialize(body),System.Text.Encoding.UTF8,"application/json"))){string raw=await response.Content.ReadAsStringAsync();var value=json.Deserialize<Dictionary<string,object>>(raw);if(!response.IsSuccessStatusCode)throw new Exception(value.ContainsKey("error")?value["error"].ToString():"HTTP error");return value;}}
    static Dictionary<string,object> Obj(object v){return v as Dictionary<string,object>??new Dictionary<string,object>();}static string Str(Dictionary<string,object> v,string k){return v.ContainsKey(k)&&v[k]!=null?v[k].ToString():"—";}static bool Bool(Dictionary<string,object> v,string k){return v.ContainsKey(k)&&v[k] is bool&&(bool)v[k];}static object[] Arr(object v){var array=v as object[];if(array!=null)return array;var list=v as System.Collections.IList;if(list==null)return new object[0];var result=new object[list.Count];list.CopyTo(result,0);return result;}
    static string Translate(string state){var labels=new Dictionary<string,string>{{"running","Работает"},{"paused","Пауза"},{"stopped","Остановлен"},{"assigned","Назначен"},{"installed","Установлен"},{"starting","Запускается"},{"waiting","Ожидает"},{"error","Ошибка"},{"downloading","Загружается"},{"pending","Ожидает отправки"},{"received","Получено"},{"applied","Применено"},{"receiving","Принимает настройки"}};return labels.ContainsKey(state)?labels[state]:state;}
    static string Step(string value){var labels=new Dictionary<string,string>{{"farming","Фарм"},{"monitoring","Наблюдение"},{"revive","Возрождение"},{"waiting_after_revive","Ожидание после возрождения"},{"restore_stats","Восстановление характеристик"},{"buy_supplies","Закупка расходников"},{"auto_purchase","Автоматическая закупка"},{"red_weight_dismantle","Разбор при перегрузе"},{"open_farm_map","Открытие карты"},{"verify_arrival","Проверка прибытия"},{"verify_map_marker","Проверка точки на карте"},{"enable_autobattle","Включение автобоя"},{"recognizing_screen","Распознавание экрана"},{"screen_locked","Экран заблокирован"},{"manual_control","Ручное управление"},{"accessibility_permission_required","Нужна служба специальных возможностей"},{"game_not_foreground","Игра не на экране"},{"unrecognized_game_screen","Неизвестный экран игры"},{"farm_point_required","Нужна точка фарма"},{"launch_game","Запуск игры"},{"waiting_game_launch","Ожидание запуска игры"},{"wake_power_saving","Выход из игрового энергосбережения"}};return labels.ContainsKey(value)?labels[value]:value;}
    static string StatusLine(Dictionary<string,object> bot,Dictionary<string,object> saved){string when="—";if(bot.ContainsKey("updatedAt"))try{when=new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(Convert.ToDouble(bot["updatedAt"])).ToLocalTime().ToString("HH:mm:ss");}catch{}return "Шаг: "+Step(Str(bot,"step"))+" · точка: "+Str(bot,"activePoint")+" · отчёт: "+when+"\nНастройки: "+(Bool(saved,"pending")?"ожидают отправки":Translate(Str(bot,"settingsStatus")))+" · получено / применено: "+Str(bot,"receivedRevision")+" / "+Str(bot,"appliedRevision")+" · причина: "+Step(Str(bot,"reason"))+" · ошибка: "+Step(Str(bot,"error"));}
    async Task RefreshPhones(){
        if(loading)return;loading=true;
        bool scoped=!String.IsNullOrEmpty(deviceId);deviceAvailable=false;
        try{
            var result=await Request("GET","/bot/v1/phones");phones.Rows.Clear();int select=-1;
            foreach(var raw in Arr(result["phones"])){var p=Obj(raw);var bot=Obj(p.ContainsKey("bot")?p["bot"]:null);var saved=Obj(p.ContainsKey("profile")?p["profile"]:null);
                var row=phones.Rows[phones.Rows.Add(PhoneTitle(p,saved),Bool(p,"online")?"Доступен":"Не в сети",Str(bot,"botId")+" / "+Str(bot,"version"),(Bool(p,"online")?"":"Последнее: ")+Translate(Str(bot,"status")))];
                string botState=Str(bot,"status");row.Cells[3].Style.ForeColor=botState=="error"?Color.FromArgb(255,137,137):botState=="running"?Mint:Color.Silver;row.Tag=Str(p,"id");
                if((string)row.Tag==selected){select=row.Index;deviceAvailable=true;if(!dirty)status.Text=Translate(botState)+" · "+Step(Str(bot,"step"))+" · Настройки: "+(Bool(saved,"pending")?"ожидают отправки":Translate(Str(bot,"settingsStatus")));
                    liveState.Text="Состояние: "+Translate(botState);liveState.ForeColor=botState=="running"?Mint:botState=="error"?Color.FromArgb(255,137,137):Color.Silver;liveStep.Text="Шаг: "+Step(Str(bot,"step"));liveRevision.Text="Профиль: "+Str(bot,"appliedRevision")+" / "+Str(bot,"receivedRevision")+" · "+Translate(Str(bot,"settingsStatus"));
                    if(scoped){deviceHeading.Text=PhoneTitle(p,saved);Text="Phone Exit · "+deviceHeading.Text;deviceInfo.Text=(Bool(p,"online")?"В сети":"Не в сети · настройки сохраняются на ПК")+" · Бот: "+Str(bot,"botId")+" · "+Str(bot,"version")+" · "+Translate(botState);errorInfo.Text="Последний отчёт телефона\n\n"+StatusLine(bot,saved);}}
            }
            if(select>=0)phones.Rows[select].Selected=true;
            else if(scoped){phones.ClearSelection();deviceHeading.Text="Телефон недоступен";deviceInfo.Text="Устройство отсутствует в личном списке.";status.Text="Выбранный телефон не найден. Другое устройство не выбрано.";}
            else if(phones.Rows.Count>0){phones.Rows[0].Selected=true;selected=phones.Rows[0].Tag as string;profile=null;}
        }catch{status.Text="HTTP API недоступен. Данные не обновлены.";if(scoped)deviceInfo.Text="Нет связи с локальным сервисом.";}
        finally{loading=false;}
        if(profile==null&&selected!=null&&(!scoped||deviceAvailable))await LoadProfile();
        if(scoped){foreach(var action in actions)action.Enabled=deviceAvailable&&settings!=null&&!busy;for(int i=0;i<3;i++)deviceTabs.TabPages[i].Enabled=deviceAvailable&&settings!=null;}
        UpdateGameView();
    }
    static string PhoneTitle(Dictionary<string,object> phone,Dictionary<string,object> saved){var identity=Obj(saved.ContainsKey("identity")?saved["identity"]:null);string name=Str(identity,"characterName"),provider=Str(identity,"provider");return (name!="—"&&name!=""?name+" · ":"")+Str(phone,"name")+" · "+Str(phone,"country")+(provider!="—"&&provider!=""?" · "+provider:"");}
    void EditIdentity(){var identity=Obj(profile.ContainsKey("identity")?profile["identity"]:null);using(var dialog=new BotWindow{Text="Персонаж и поставщик телефона",Size=new Size(600,460),StartPosition=FormStartPosition.CenterParent}){var fields=new DarkFlowPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};var name=new TextBox{Width=480,MaxLength=80,BackColor=Surface,ForeColor=Color.White,Text=Str(identity,"characterName")=="—"?"":Str(identity,"characterName")};var provider=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Surface,ForeColor=Color.White};provider.Items.AddRange(new object[]{"Не указан","VMOS","UgPhone","Другое"});provider.SelectedItem=Str(identity,"provider");if(provider.SelectedIndex<0)provider.SelectedIndex=0;fields.Controls.Add(new Label{Text="Имя персонажа",AutoSize=true});fields.Controls.Add(name);fields.Controls.Add(new Label{Text="Поставщик телефона",AutoSize=true,Margin=new Padding(3,16,3,3)});fields.Controls.Add(provider);var save=new BotButton{Text="Сохранить",Width=480,Height=44,BackColor=Mint,ForeColor=Background,Margin=new Padding(3,20,3,3)};fields.Controls.Add(save);save.Click+=async(s,e)=>{save.Enabled=false;try{var result=await Request("POST","/bot/v1/devices/"+selected+"/identity",new{characterName=name.Text,provider=provider.SelectedIndex==0?"":Convert.ToString(provider.SelectedItem)});profile["identity"]=result["identity"];await RefreshPhones();dialog.Close();}catch(Exception error){MessageBox.Show(dialog,error.Message,"Не удалось сохранить");save.Enabled=true;}};dialog.Controls.Add(fields);fields.BringToFront();dialog.ShowDialog(this);}}
    async Task LoadProfile(){loading=true;try{profile=await Request("GET","/bot/v1/devices/"+selected+"/profile");profileGame=Str(profile,"botId");chosenGame=profileGame;syncingGame=true;gameSelect.SelectedIndex=gameModules.FindIndex(m=>Str(m,"id")==profileGame);syncingGame=false;settings=Obj(profile["settings"]);farm.Checked=Bool(settings,"farm_enabled");recovery.Checked=Bool(settings,"recovery_enabled");dismantle.Checked=Bool(settings,"auto_dismantle_enabled");autostart.Checked=Bool(settings,"autostart_enabled");points.Clear();pointUndo.Clear();undoPointButton.Enabled=false;CancelPointMove();if(LordNineSettings&&settings.ContainsKey("farm_map_spots"))foreach(var p in Arr(settings["farm_map_spots"]))points.Add(Obj(p));RefreshSpots(points.FindIndex(p=>Str(p,"id")==Str(settings,"active_farm_map_spot_id")));dirty=false;status.Text=Bool(profile,"pending")?"Настройки сохранены на ПК, ожидают передачи телефону.":"Профиль загружен.";}catch{status.Text="Не удалось прочитать настройки телефона.";}finally{loading=false;syncingGame=false;UpdateGameView();}}
    async Task LoadMaps(){try{var bytes=await http.GetByteArrayAsync("/bot/v1/assets/lordnine/index.json");var index=json.Deserialize<Dictionary<string,object>>(System.Text.Encoding.UTF8.GetString(bytes));foreach(var item in Arr(index["maps"])){var m=Obj(item);mapItems.Add(m);maps.Items.Add(Str(m,"label"));if(!regions.Items.Contains(Str(m,"tab_label")))regions.Items.Add(Str(m,"tab_label"));}if(maps.Items.Count>0)maps.SelectedIndex=0;}catch{status.Text="Карты Lord Nine недоступны.";}}
    void LoadMap(){
        CancelPointMove();
        Image old=picture.Image;picture.Image=null;if(old!=null)old.Dispose();
        if(maps.SelectedIndex<0){mapStatus.Text="Карта не выбрана";return;}
        RefreshNavigation();
        var map=mapItems[maps.SelectedIndex];syncRegion=true;try{regions.SelectedItem=Str(map,"tab_label");}finally{syncRegion=false;}
        string file=Path.Combine(root,"lordnine","maps",Str(map,"image"));
        if(!File.Exists(file)){mapStatus.Text="Изображение карты недоступно: "+Str(map,"label");picture.Invalidate();return;}
        try{using(var stream=File.OpenRead(file))using(var bitmap=new Bitmap(stream)){var crop=wholeMap?new Rectangle(0,0,bitmap.Width,bitmap.Height):Rectangle.FromLTRB((int)(bitmap.Width*.265),(int)(bitmap.Height*.095),(int)(bitmap.Width*.735),(int)(bitmap.Height*.945));mapCrop=new RectangleF(crop.X/(float)bitmap.Width,crop.Y/(float)bitmap.Height,crop.Width/(float)bitmap.Width,crop.Height/(float)bitmap.Height);picture.Image=bitmap.Clone(crop,bitmap.PixelFormat);}
            mapStatus.Text=Str(map,"tab_label")+" / "+Str(map,"label");SetZoom(1);pointList.AutoScrollPosition=Point.Empty;RefreshPointList();picture.Invalidate();
        }catch{mapStatus.Text="Не удалось прочитать изображение карты: "+Str(map,"label");}
    }
    Rectangle ImageRect(){if(picture.Image==null)return Rectangle.Empty;double scale=Math.Min(picture.Width/(double)picture.Image.Width,picture.Height/(double)picture.Image.Height);int w=(int)(picture.Image.Width*scale),h=(int)(picture.Image.Height*scale);return new Rectangle((picture.Width-w)/2,(picture.Height-h)/2,w,h);}
    void SetPointTool(string tool){CancelPointMove();pointTool=tool;foreach(var pair in pointTools){pair.Value.BackColor=pair.Key==tool?Mint:Surface;pair.Value.ForeColor=pair.Key==tool?Background:Color.White;pair.Value.Invalidate();}picture.Cursor=tool=="move"?Cursors.SizeAll:tool=="delete"?Cursors.No:Cursors.Cross;}
    Dictionary<string,object> EditingSpot(){if(busy||settings==null||spots.SelectedIndex<0||maps.SelectedIndex<0||picture.Image==null)return null;var spot=points[spots.SelectedIndex];return Str(spot,"map_id")==Str(mapItems[maps.SelectedIndex],"id")?spot:null;}
    object[] MapPoint(Point at){Rectangle r=ImageRect();if(r.IsEmpty||!r.Contains(at))return null;return new object[]{mapCrop.X+mapCrop.Width*(at.X-r.X)/(double)r.Width,mapCrop.Y+mapCrop.Height*(at.Y-r.Y)/(double)r.Height};}
    int HitPoint(Dictionary<string,object> spot,Point at){Rectangle r=ImageRect();var list=Arr(spot["map_points"]);int nearest=-1;double distance=14*14;for(int i=0;i<list.Length;i++){var xy=Arr(list[i]);if(xy.Length!=2)continue;double dx=r.X+(Convert.ToDouble(xy[0])-mapCrop.X)/mapCrop.Width*r.Width-at.X,dy=r.Y+(Convert.ToDouble(xy[1])-mapCrop.Y)/mapCrop.Height*r.Height-at.Y;double d=dy>=0&&dy<=30&&Math.Abs(dx)<=16*dy/30?0:dx*dx+dy*dy;if(d<=distance){distance=d;nearest=i;}}return nearest;}
    void RememberPointEdit(Dictionary<string,object> spot){pointUndo.Add(new Dictionary<string,object>{{"id",Str(spot,"id")},{"map_points",json.DeserializeObject(json.Serialize(spot["map_points"]))},{"teleport_point",spot.ContainsKey("teleport_point")?json.DeserializeObject(json.Serialize(spot["teleport_point"])):null},{"dirty",dirty}});if(pointUndo.Count>100)pointUndo.RemoveAt(0);undoPointButton.Enabled=true;}
    void UndoPointEdit(){if(busy||settings==null)return;CancelPointMove();while(pointUndo.Count>0){int last=pointUndo.Count-1;var edit=pointUndo[last];pointUndo.RemoveAt(last);int index=points.FindIndex(p=>Str(p,"id")==Str(edit,"id"));if(index<0)continue;points[index]["map_points"]=edit["map_points"];points[index]["teleport_point"]=edit["teleport_point"];dirty=Bool(edit,"dirty")||dirty;RefreshSpots(index);status.Text="Изменение точек отменено. Настройки телефона не отправлялись.";break;}undoPointButton.Enabled=pointUndo.Count>0;}
    void FinishPointEdit(){dirty=true;RefreshPointList();picture.Invalidate();}
    void PlacePoint(MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;var spot=EditingSpot();var point=MapPoint(e.Location);if(spot==null||point==null)return;var list=new List<object>(Arr(spot["map_points"]));int near=HitPoint(spot,e.Location);if(pointTool=="delete"){if(near<0)return;RememberPointEdit(spot);list.RemoveAt(near);spot["map_points"]=list.ToArray();}else if(pointTool=="teleport"){if(IsChainedRoute(spot)){status.Text="Телепорт задаётся маршрутом этой локации.";return;}RememberPointEdit(spot);spot["teleport_point"]=point;}else if(pointTool=="add"){if(near>=0||list.Count>=256)return;RememberPointEdit(spot);list.Add(point);spot["map_points"]=list.ToArray();}else return;FinishPointEdit();}
    void BeginPointMove(MouseEventArgs e){if(pointTool!="move"||e.Button!=MouseButtons.Left)return;var spot=EditingSpot();if(spot==null)return;movingPoint=HitPoint(spot,e.Location);if(movingPoint>=0){movingPreview=e.Location;picture.Capture=true;}}
    void CancelPointMove(){movingPoint=-1;movingPreview=null;picture.Capture=false;picture.Invalidate();}
    void EndPointMove(MouseEventArgs e){int index=movingPoint;var spot=EditingSpot();var point=MapPoint(e.Location);CancelPointMove();if(e.Button!=MouseButtons.Left||index<0||spot==null||point==null)return;var list=new List<object>(Arr(spot["map_points"]));if(index>=list.Count)return;RememberPointEdit(spot);list[index]=point;spot["map_points"]=list.ToArray();FinishPointEdit();}
    void PaintPoints(Graphics g){if(picture.Image==null||spots.SelectedIndex<0||maps.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];if(Str(spot,"map_id")!=Str(mapItems[maps.SelectedIndex],"id"))return;Rectangle r=ImageRect();int number=0;foreach(var p in Arr(spot["map_points"])){var xy=Arr(p);if(xy.Length==2)DrawPoint(g,r,xy,Mint,(++number).ToString());}if(spot.ContainsKey("teleport_point"))DrawPoint(g,r,Arr(spot["teleport_point"]),Color.Orange,"T");if(movingPreview.HasValue){var p=movingPreview.Value;using(var pen=new Pen(Mint,2)){g.DrawEllipse(pen,p.X-9,p.Y-9,18,18);g.DrawLine(pen,p.X-12,p.Y,p.X+12,p.Y);g.DrawLine(pen,p.X,p.Y-12,p.X,p.Y+12);}}}
    void DrawPoint(Graphics g,Rectangle r,object[] p,Color color,string label){if(p.Length!=2||r.IsEmpty)return;float nx=(float)Convert.ToDouble(p[0]),ny=(float)Convert.ToDouble(p[1]);if(!mapCrop.Contains(nx,ny))return;float x=r.X+(nx-mapCrop.X)/mapCrop.Width*r.Width,y=r.Y+(ny-mapCrop.Y)/mapCrop.Height*r.Height;g.SmoothingMode=SmoothingMode.AntiAlias;var triangle=new[]{new PointF(x-16,y-30),new PointF(x+16,y-30),new PointF(x,y)};using(var shadow=new Pen(Background,4))g.DrawPolygon(shadow,triangle);using(var fill=new SolidBrush(color))g.FillPolygon(fill,triangle);using(var pen=new Pen(Color.White,1))g.DrawPolygon(pen,triangle);using(var font=new Font("Segoe UI",9,FontStyle.Bold))using(var ink=new SolidBrush(Background))using(var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})g.DrawString(label,font,ink,new RectangleF(x-14,y-30,28,20),format);}
