    static bool NearPoint(object[] a,object[] b){if(a.Length!=2||b.Length!=2)return false;return Math.Pow(Convert.ToDouble(a[0])-Convert.ToDouble(b[0]),2)+Math.Pow(Convert.ToDouble(a[1])-Convert.ToDouble(b[1]),2)<=.025*.025;}
    void SetZoom(double value){zoom=Math.Max(.5,Math.Min(4,value));zoomLabel.Text=Math.Round(zoom*100)+"%";ResizeMap();}
    void ResizeMap(){if(picture.Image==null)return;double fit=Math.Min(Math.Max(1,mapViewport.Width-20)/(double)picture.Image.Width,Math.Max(1,mapViewport.Height-20)/(double)picture.Image.Height);picture.Size=new Size(Math.Max(1,(int)(picture.Image.Width*fit*zoom)),Math.Max(1,(int)(picture.Image.Height*fit*zoom)));PositionMap(new Point((mapViewport.ClientSize.Width-picture.Width)/2,(mapViewport.ClientSize.Height-picture.Height)/2));picture.Invalidate();}
    void PositionMap(Point position){position.X=picture.Width<=mapViewport.Width?(mapViewport.Width-picture.Width)/2:Math.Max(mapViewport.Width-picture.Width,Math.Min(0,position.X));position.Y=picture.Height<=mapViewport.Height?(mapViewport.Height-picture.Height)/2:Math.Max(mapViewport.Height-picture.Height,Math.Min(0,position.Y));picture.Location=position;}
    void ZoomMapAt(Point at,int delta){if(picture.Image==null||delta==0)return;double x=(at.X-picture.Left)/(double)picture.Width,y=(at.Y-picture.Top)/(double)picture.Height;SetZoom(zoom*Math.Pow(1.25,delta/120.0));PositionMap(new Point((int)Math.Round(at.X-x*picture.Width),(int)Math.Round(at.Y-y*picture.Height)));}
    static bool IsChainedRoute(Dictionary<string,object> spot){var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);if(plan.ContainsKey("enabled")&&!Bool(plan,"enabled"))return false;string type=Str(plan,"type");return type=="tyriosa_floor_chain"||type=="deadmans_district_chain"||Str(spot,"map_id").Contains("tyriosa");}
