    void AddMoveRows(Dictionary<string,object> spot,bool chain){
        var map=mapItems.Find(m=>Str(m,"id")==Str(spot,"map_id"));if(map==null)return;string file=Path.Combine(root,"lordnine","maps",Str(map,"image"));if(!File.Exists(file))return;
        var teleport=Arr(spot.ContainsKey("teleport_point")?spot["teleport_point"]:null);var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);if(chain&&Str(plan,"type")=="deadmans_district_chain")return;string target=Str(plan,"target_floor");string id=Str(spot,"map_id");int routeRow=id.Contains("3f")||target=="3F"?1:0;
        try{using(var stream=File.OpenRead(file))using(var bitmap=new Bitmap(stream)){for(int i=0;i<MoveRowCenters.Length;i++){
            if(chain&&i!=routeRow)continue;double y=MoveRowCenters[i];var rect=Rectangle.FromLTRB((int)(bitmap.Width*.745),(int)(bitmap.Height*(y-.029)),(int)(bitmap.Width*.955),(int)(bitmap.Height*(y+.029)));var crop=bitmap.Clone(rect,bitmap.PixelFormat);
            int bright=0,edges=0,count=0;for(int py=0;py<crop.Height;py+=2)for(int px=0;px<crop.Width;px+=2){var c=crop.GetPixel(px,py);int gray=(c.R+c.G+c.B)/3;if(gray>55)bright++;if(px>1){var previous=crop.GetPixel(px-2,py);if(Math.Abs(gray-(previous.R+previous.G+previous.B)/3)>50)edges++;}count++;}
            if(!chain&&bright/(double)Math.Max(1,count)<.015&&edges/(double)Math.Max(1,count)<.015){crop.Dispose();continue;}
            int row=i;var button=new MoveRowButton{Image=crop,Width=Math.Max(160,pointList.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-12),AccessibleName=chain?"Переход маршрута · Move #"+(i+1):"Fast Travel "+(i+1),Enabled=!chain,SelectedRow=teleport.Length==2&&Math.Abs(Convert.ToDouble(teleport[0])-(.735+.47*(.986-.735)))<=.030&&Math.Abs(Convert.ToDouble(teleport[1])-y)<=.030,Margin=new Padding(3,3,3,3)};toolTips.SetToolTip(button,button.AccessibleName);button.Click+=(s,e)=>SelectTeleportRow(row);pointList.Controls.Add(button);
        }}}catch{pointList.Controls.Add(new Label{Text="Список Move недоступен",AutoSize=true,ForeColor=Color.Silver});}
    }
