        var scroll=pointList.AutoScrollPosition;foreach(Control control in new List<Control>(SnapshotControls(pointList)))if(control!=routeLabel)control.Dispose();pointList.Controls.Clear();actions.RemoveAll(b=>b.IsDisposed);foreach(var button in new List<Button>(buttonCommands.Keys))if(button.IsDisposed)buttonCommands.Remove(button);pointList.FlowDirection=FlowDirection.TopDown;pointList.WrapContents=false;
