    async Task<Dictionary<string,object>> WaitJob(Dictionary<string,object> job){for(int i=0;i<180;i++){await Task.Delay(1000);var result=await Request("GET","/bot/v1/jobs/"+Str(job,"id"));if(Str(result,"status")=="failed")throw new Exception(Str(result,"error"));if(Str(result,"status")=="done")return Obj(result["result"]);}throw new Exception("Результат неизвестен; повторно не отправляется.");}
    async Task InspectMap(bool capture){if(dirty){status.Text="Сначала сохраните настройки.";return;}if(spots.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];await Guard(async()=>{status.Text="Фарм приостановлен. Проверяется Current Location и стрелка на телефоне…";var job=await Request("POST","/bot/v1/devices/"+selected+"/action",new{op="editor",kind=capture?"capture":"point",mapId=Str(spot,"map_id")});var result=await WaitJob(job);if(!capture){var xy=Arr(result["point"]);var list=new List<object>(Arr(spot["map_points"]));int near=list.FindIndex(item=>NearPoint(Arr(item),xy));if(near>=0)list[near]=xy;else{if(list.Count>=256)throw new Exception("Не более 256 точек.");list.Add(xy);}spot["map_points"]=list.ToArray();dirty=true;RefreshPointList();picture.Invalidate();status.Text="Положение добавлено в редактор. Сохраните настройки. Бот оставлен на паузе.";return;}var shotJob=await Request("POST","/v1/devices/"+selected+"/commands",new{command="screenshot",args=new{format="png"}});Dictionary<string,object> shot=null;for(int i=0;i<90;i++){await Task.Delay(1000);var response=await Request("GET","/v1/devices/"+selected+"/commands/"+Str(shotJob,"id"));if(Str(response,"status")=="done"){var envelope=Obj(response["result"]);if(!Bool(envelope,"ok"))throw new Exception("Не получен кадр.");shot=Obj(envelope["result"]);break;}}if(shot==null)throw new Exception("Не получен кадр.");using(var stream=new MemoryStream(Convert.FromBase64String(Str(shot,"image"))))using(var bitmap=new Bitmap(stream)){var rect=Rectangle.FromLTRB((int)Math.Round(bitmap.Width*.015),(int)Math.Round(bitmap.Height*.065),(int)Math.Round(bitmap.Width*.385),(int)Math.Round(bitmap.Height*.17));using(var crop=bitmap.Clone(rect,bitmap.PixelFormat)){using(var png=new MemoryStream()){crop.Save(png,System.Drawing.Imaging.ImageFormat.Png);var templates=Obj(settings.ContainsKey("current_location_templates")?settings["current_location_templates"]:null);templates[Str(spot,"map_id")]=Convert.ToBase64String(png.