    async Task CopyFrom(){if(busy)return;using(var dialog=new BotWindow{Text="Копировать настройки фарма с телефона",Size=new Size(520,420),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White};var ids=new List<string>();foreach(DataGridViewRow row in phones.Rows)if((string)row.Tag!=selected){ids.Add((string)row.Tag);list.Items.Add(row.Cells[0].Value);}var ok=new BotButton{Text="Копировать в редактор",Dock=DockStyle.Bottom,Height=42,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(ok);if(dialog.ShowDialog(this)!=DialogResult.OK||list.SelectedIndex<0)return;await Guard(async()=>{var source=await Request("GET","/bot/v1/devices/"+ids[list.SelectedIndex]+"/profile");var imported=Obj(source["settings"]);if(Arr(imported["farm_map_spots"]).Length==0)throw new Exception("У телефона нет настроенных локаций.");loading=true;try{settings=imported;points.Clear();foreach(var raw in Arr(settings["farm_map_spots"]))points.Add(Obj(raw));farm.Checked=Bool(settings,"farm_enabled");recovery.Checked=Bool(settings,"recovery_enabled");dismantle.Checked=Bool(settings,"auto_dismantle_enabled");autostart.Checked=Bool(settings,"autostart_enabled");RefreshSpots(0);dirty=true;status.Text="Профиль скопирован в редактор. Проверьте точки, затем сохраните настройки.";}finally{loading=false;}});}}
