    void EditTravelPlan(){
        if(spots.SelectedIndex<0)return;
        var spot=points[spots.SelectedIndex];var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);
        using(var dialog=new BotWindow{Text="Локация и переход",Size=new Size(600,560),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White,Font=Font}){
            var fields=new DarkFlowPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16)};
            var enabled=new CheckBox{Text="Локация включена",Checked=!spot.ContainsKey("enabled")||Bool(spot,"enabled"),AutoSize=true};
            var run=new CheckBox{Text="Идти к точке фарма после телепорта",Checked=!spot.ContainsKey("run_after_teleport")||Bool(spot,"run_after_teleport"),AutoSize=true};
            var kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=450,BackColor=Surface,ForeColor=Color.White};
