            kind.SelectedIndex=!spot.ContainsKey("travel_plan")?0:!Bool(plan,"enabled")&&plan.ContainsKey("enabled")?1:Str(plan,"type")=="tyriosa_floor_chain"?2:Str(plan,"type")=="deadmans_district_chain"?3:0;
            var target=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=450,BackColor=Surface,ForeColor=Color.White};
            Action refresh=()=>{target.Items.Clear();target.Enabled=kind.SelectedIndex>=2;if(kind.SelectedIndex==2)target.Items.AddRange(new object[]{"1F","2F","3F"});else if(kind.SelectedIndex==3)target.Items.AddRange(new object[]{"1","2","3"});if(target.Items.Count>0){string old=Str(plan,kind.SelectedIndex==2?"target_floor":"target_district");int index=target.Items.IndexOf(old);target.SelectedIndex=index>=0?index:0;}};
            kind.SelectedIndexChanged+=(s,e)=>refresh();refresh();
            fields.Controls.Add(enabled);fields.Controls.Add(run);fields.Controls.Add(new Label{Text="План перехода",AutoSize=true,Margin=new Padding(0,15,0,6)});fields.Controls.Add(kind);fields.Controls.Add(new Label{Text="Целевой этаж / район",AutoSize=true});fields.Controls.Add(target);
            fields.Controls.Add(new Label{Text="Изменения сохранятся только после отправки настроек телефона.",Width=450,Height=42,ForeColor=Color.Silver});
            var ok=new BotButton{Text="Применить в редакторе",Dock=DockStyle.Bottom,Height=42,DialogResult=DialogResult.OK,BackColor=Mint,ForeColor=Background,FlatStyle=FlatStyle.Flat};dialog.Controls.Add(fields);dialog.Controls.Add(ok);
            if(dialog.ShowDialog(this)!=DialogResult.OK)return;
