            var heading=new Label{Text="Источник: "+source+"\nПолучатели:",Dock=DockStyle.Top,Height=78,Padding=new Padding(12),ForeColor=Mint};
            var list=new CheckedListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White,BorderStyle=BorderStyle.None,CheckOnClick=true};
            var ids=new List<string>();foreach(DataGridViewRow row in phones.Rows)if((string)row.Tag!=selected){string id=(string)row.Tag;ids.Add(id);list.Items.Add(row.Cells[0].Value,Array.IndexOf(InitialCopyTargets??new string[0],id)>=0);}
            var ok=new BotButton{Text="Скопировать сохранённые настройки",Dock=DockStyle.Bottom,Height=44,DialogResult=DialogResult.OK,BackColor=Mint,ForeColor=Background};
            dialog.Controls.Add(list);dialog.Controls.Add(heading);dialog.Controls.Add(ok);list.BringToFront();
            if(dialog.ShowDialog(this)==DialogResult.OK){var targets=new List<string>();foreach(int index in list.CheckedIndices)targets.Add(ids[index]);if(targets.Count==0){status.Text="Не выбраны телефоны для копирования.";return;}await Guard(async()=>{await Request("POST","/bot/v1/devices/"+selected+"/copy",new{targets=targets});status.Text="Копии сохранены; передача выполняется назначенным телефонам.";});}
        }
    }
    void ImportProfile(){if(settings==null||busy)return;try{using(var file=new OpenFileDialog{Title="Откройте runtime/windows.json из MultiBot",Filter="Профили MultiBot (*.json)|*.json"}){if(file.ShowDialog(this)!=DialogResult.OK)return;if(new FileInfo(file.FileName).Length>16000000)throw new Exception();var parser=new JavaScriptSerializer{MaxJsonLength=16000000};var data=parser.Deserialize<Dictionary<string,object>>(File.ReadAllText(file.FileName));var records=Obj(data.ContainsKey("windows")?data["windows"]:null);var eligible=new List<Dictionary<string,object>>();using(var dialog=new BotWindow{Text="Сопоставьте старое устройство с выбранным телефоном",Size=new Size(560,360),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White};foreach(var pair in records){var record=Obj(pair.Value);if(Str(record,"game_id")!="lordnine")continue;eligible.Add(record);list.Items.Add(Str(record,"alias")+" · "+Str(record,"name"));}var ok=new BotButton{Text="Импортировать в редактор выбранного телефона",Dock=DockStyle.Bottom,Height=44,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(ok);if(dialog.ShowDialog(this)!=DialogResult.OK||list.SelectedIndex<0)return;var source=eligible[list.SelectedIndex];points.Clear();foreach(var raw in Arr(source["farm_map_spots"])){var original=Obj(raw);var point=new Dictionary<string,object>();foreach(var key in new[]{"id","map_id","label","enabled","teleport_point","run_after_teleport","map_points","travel_plan"})if(original.ContainsKey(key))point[key]=original[key];points.Add(point);}settings["active_farm_map_spot_id"]=source.ContainsKey("active_farm_map_spot_id")?source["active_farm_map_spot_id"]:null;farm.Checked=Bool(source,"farm_enabled");dirty=true;RefreshSpots(0);status.Text="Профиль импортирован в редактор. Проверьте телефон, локацию и точки, затем сохраните настройки.";}}}catch{status.Text="Не удалось импортировать профиль: выберите windows.json с записями Lord Nine.";}}
}}
